import{_ as t,o as a,c as s,a5 as o}from"./chunks/framework.CXroN2RO.js";const r="/study/images/tools/terminal-shell-and-commands.svg",g=JSON.parse('{"title":"ターミナル・シェル・コマンドの基本","description":"","frontmatter":{"title":"ターミナル・シェル・コマンドの基本","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"文字でコマンドを操作する画面から、ターミナルとシェル、引数、カレントディレクトリ、PATH、標準入出力、パイプをPowerShellの小さな例で説明する。","aliases":["ターミナル","terminal","シェル","shell","CLI","コマンド","PowerShell","Bash","sh","cmd","引数","カレントディレクトリ","PATH","標準入力","標準出力","パイプ"],"verification":"Microsoftの公式資料に照合。掲載した表示用コマンド5種をPowerShellで実行確認（2026-11-07）"}},"headers":[],"relativePath":"tools/terminal-shell-and-commands.md","filePath":"tools/terminal-shell-and-commands.md"}'),l={name:"tools/terminal-shell-and-commands.md"};function i(n,e,h,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="ターミナル・シェル・コマンドの基本" tabindex="-1">ターミナル・シェル・コマンドの基本 <a class="header-anchor" href="#ターミナル・シェル・コマンドの基本" aria-label="Permalink to &quot;ターミナル・シェル・コマンドの基本&quot;">​</a></h1><p>開発手順には、<code>dotnet build</code>や<code>cmake --build build</code>のように文字で道具を呼ぶ操作が出てきます。このような操作方法を**CLI（コマンドラインインターフェース）**と呼びます。何を入力し、どのプログラムが受け取るのかを追うと、コマンドの読み方が分かります。<a href="https://learn.microsoft.com/en-us/windows/terminal/" target="_blank" rel="noreferrer">Windows Terminalの概要</a></p><h2 id="画面と、入力を解釈するプログラム" tabindex="-1">画面と、入力を解釈するプログラム <a class="header-anchor" href="#画面と、入力を解釈するプログラム" aria-label="Permalink to &quot;画面と、入力を解釈するプログラム&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名前</th><th>役割</th><th>例</th></tr></thead><tbody><tr><td><strong>ターミナル</strong></td><td>文字の入力や出力を表示し、コマンドラインのアプリを使う画面を提供する。</td><td>Windows Terminal、IDE内のターミナル。</td></tr><tr><td><strong>シェル</strong></td><td>入力したコマンドを解釈し、内部の機能や外部プログラムを呼び出す。</td><td>PowerShell、Bash、<code>cmd.exe</code>。</td></tr><tr><td><strong>コマンド</strong></td><td>シェルへ依頼する処理。</td><td>ファイルを一覧表示する、ビルドツールを起動する。</td></tr></tbody></table><p>同じターミナルでも、開いたタブで動くシェルを変えられます。PowerShell、Bash、cmdでは、変数や引数、パイプなどの規則が異なります。手順に書かれた対象のシェルを確認して入力します。<code>sh</code>はPOSIXのシェル言語に沿った実行環境の入口として使われる名前で、Bashは独自の追加機能も持つシェルです。<a href="https://learn.microsoft.com/en-us/windows/terminal/faq#what-is-the-difference-between-a-shell-and-a-terminal" target="_blank" rel="noreferrer">Windows Terminalとシェルの関係</a> · <a href="https://www.gnu.org/software/bash/manual/html_node/What-is-Bash_003f.html" target="_blank" rel="noreferrer">Bashの公式マニュアル</a></p><figure class="study-figure"><img src="'+r+`" alt="ターミナルで文字を入力し、PowerShellがコマンドを解釈する。Get-ChildItemはシェルのコマンドレットとして動き、dotnet buildは外部のdotnetプログラムを起動する。出力はターミナルに表示される。" width="760" height="442" loading="lazy"><figcaption>シェル内の機能を使う場合と、別のプログラムを起動する場合があります。<a href="/study/images/tools/terminal-shell-and-commands.svg" target="_blank" rel="noopener noreferrer">シェルとコマンドの図を拡大</a></figcaption></figure><h2 id="コマンド名と引数を読む" tabindex="-1">コマンド名と引数を読む <a class="header-anchor" href="#コマンド名と引数を読む" aria-label="Permalink to &quot;コマンド名と引数を読む&quot;">​</a></h2><p>PowerShellでは、<code>Get-ChildItem -File</code>を「<code>Get-ChildItem</code>に<code>-File</code>という指定を渡す」と読めます。<code>Get-ChildItem</code>はPowerShellの<strong>コマンドレット</strong>で、<code>-File</code>はファイルを対象にするパラメーターです。<code>dotnet build</code>なら、<code>dotnet</code>という外部プログラムへ<code>build</code>を引数として渡します。<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/get-childitem" target="_blank" rel="noreferrer">Get-ChildItem</a> · <a href="https://learn.microsoft.com/en-us/dotnet/core/tools/dotnet-build" target="_blank" rel="noreferrer">dotnet build</a></p><p>シェルはコマンド名やパス、引用符などを解釈してから処理を呼び出します。例えばPowerShellで空白を含むパスを値として渡すときは、<code>&#39;D:\\My Game\\assets&#39;</code>のように引用符でまとめます。以下では、PowerShellに標準で入っているコマンドレットを使います。<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_parsing" target="_blank" rel="noreferrer">PowerShellの引数の解釈</a></p><h2 id="まず現在地とファイルを表示する" tabindex="-1">まず現在地とファイルを表示する <a class="header-anchor" href="#まず現在地とファイルを表示する" aria-label="Permalink to &quot;まず現在地とファイルを表示する&quot;">​</a></h2><p>次の例をPowerShellで一行ずつ実行します。ファイル名や件数は、開いたフォルダーによって変わります。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Location</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ChildItem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ChildItem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">First </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Length</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Get-ChildItem</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Write-Output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;hello&#39;</span></span></code></pre></div><p><strong>カレントディレクトリ</strong>は、いま作業の基準にしている場所です。<code>Get-Location</code>で現在地を、<code>Get-ChildItem</code>でその中身を確認できます。ファイルシステム上の場所では、<code>.</code>は現在のフォルダー、<code>..</code>は親フォルダーを示します。<code>Set-Location</code>で作業場所を移せます。相対パスは基準の場所と組み合わせて読みます。<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/get-location" target="_blank" rel="noreferrer">Get-Location</a> · <a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/set-location" target="_blank" rel="noreferrer">Set-Location</a> · <a href="/study/os/files-and-paths.html">ファイルとパス</a></p><h2 id="コマンドがどこから見つかるか" tabindex="-1">コマンドがどこから見つかるか <a class="header-anchor" href="#コマンドがどこから見つかるか" aria-label="Permalink to &quot;コマンドがどこから見つかるか&quot;">​</a></h2><p><code>Get-Command Get-ChildItem</code>は、指定した名前に対応するコマンドの情報を表示します。外部プログラムの名前をパスなしで入力したとき、シェルは<strong>PATH環境変数</strong>に登録されたフォルダーなどから探します。開発ツールのインストール状況やシェルを開いた方法によって、見つかるプログラムが変わることがあります。<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/get-command" target="_blank" rel="noreferrer">Get-Command</a> · <a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_command_precedence" target="_blank" rel="noreferrer">PowerShellのコマンドの検索順</a></p><p>PowerShellで現在のフォルダーにある自作の実行ファイルを起動するときは、次のように先頭に<code>.\\</code>を付けます。パスを含めて指定することで、どのファイルを起動するかを表せます。以下は<code>Game.exe</code>をその場所にビルド済みの場合の例です。<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_command_precedence" target="_blank" rel="noreferrer">PowerShellで現在のフォルダーのプログラムを実行する</a></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Game.exe</span></span></code></pre></div><h2 id="出力を次の処理へ渡す" tabindex="-1">出力を次の処理へ渡す <a class="header-anchor" href="#出力を次の処理へ渡す" aria-label="Permalink to &quot;出力を次の処理へ渡す&quot;">​</a></h2><p><code>Get-ChildItem -File | Select-Object -First 3 Name, Length</code>の<code>|</code>は<strong>パイプ</strong>です。左側が出力したものを右側へ渡します。この例ではファイルを表すオブジェクトを渡し、先頭3件の名前とサイズを取り出します。PowerShellのコマンドレット間では、名前やサイズなどの情報を持つオブジェクトを受け渡せます。<a href="https://learn.microsoft.com/en-us/powershell/scripting/learn/ps101/04-pipelines" target="_blank" rel="noreferrer">PowerShellのパイプ</a></p><p>外部プログラムには、入力を受ける<strong>標準入力</strong>、通常の結果を出す<strong>標準出力</strong>、エラーなどを出す<strong>標準エラー出力</strong>という受け渡し口があります。シェルから起動したプログラムの出力を画面に表示したり、別のプログラムへつないだりできます。外部プログラム間のパイプと、PowerShellのコマンドレット間のオブジェクトの受け渡しでは、扱う形式を確認します。<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_output_streams" target="_blank" rel="noreferrer">PowerShellの出力ストリーム</a> · <a href="/study/os/pipes-and-process-io.html">パイプと子プロセスの標準入出力</a></p><p>開発環境全体の役割は<a href="/study/tools/development-tools-basics.html">開発ツールの基本</a>、ソースからプログラムを作る処理は<a href="/study/compilers/source-code-and-execution.html">ソースコードから実行まで</a>へ進みます。</p>`,21)])])}const k=t(l,[["render",i]]);export{g as __pageData,k as default};
